from forecasting.schemas.skill import Skill


def _skill(
    skill_id: str,
    name: str,
    category: str,
    aliases: tuple[str, ...],
    description: str,
) -> Skill:
    return Skill(
        skill_id=skill_id,
        canonical_name=name,
        category=category,
        aliases=aliases,
        description=description,
    )


